// ── WF1: Parsear y Validar CSV desde binario ──────────────────────────────
const binaryData = $input.first().binary;
if (!binaryData || !binaryData.data) {
  return [{ json: { isValid: false, errors: ['No se encontró archivo CSV binario'], records: [], total: 0 } }];
}
const csvContent = Buffer.from(binaryData.data.data, 'base64').toString('utf-8');
const allLines = csvContent.trim().split('\n').filter(l => l.trim());
if (allLines.length < 2) {
  return [{ json: { isValid: false, errors: ['CSV vacío o sin datos'], records: [], total: 0 } }];
}
const headers = allLines[0].split(',').map(h => h.trim().replace(/^"|"$/g, '').toLowerCase());
const required = ['student_id', 'student_name', 'course_id', 'date', 'status'];
const missing = required.filter(f => !headers.includes(f));
if (missing.length > 0) {
  return [{ json: { isValid: false, errors: ['Campos faltantes: ' + missing.join(', ')], records: [], total: 0 } }];
}
const validStatuses = ['present', 'absent', 'late', 'excused'];
const records = [], errors = [];
for (let i = 1; i < allLines.length; i++) {
  const values = allLines[i].split(',').map(v => v.trim().replace(/^"|"$/g, ''));
  const row = {};
  headers.forEach((h, idx) => { row[h] = values[idx] !== undefined ? values[idx] : ''; });
  const errs = [];
  if (!row.student_id)   errs.push('Fila ' + (i+1) + ': student_id vacío');
  if (!row.student_name) errs.push('Fila ' + (i+1) + ': student_name vacío');
  if (!row.course_id)    errs.push('Fila ' + (i+1) + ': course_id vacío');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(row.date)) errs.push('Fila ' + (i+1) + ': fecha inválida (' + row.date + ')');
  if (!validStatuses.includes(row.status)) errs.push('Fila ' + (i+1) + ': status inválido (' + row.status + ')');
  if (errs.length > 0) errors.push(...errs);
  else records.push(row);
}
return [{ json: { isValid: errors.length === 0 && records.length > 0, errors, records, total: records.length, errorCount: errors.length, processedAt: new Date().toISOString() } }];

// ── WF1: Construir INSERT masivo ──────────────────────────────────────────
const { records } = $json;
if (!records || records.length === 0) {
  return [{ json: { ...$json, sql_query: null, insertCount: 0 } }];
}
const safe = s => String(s || '').replace(/'/g, "''");
const valueRows = records.map(r =>
  "('" + safe(r.student_id) + "','" + safe(r.student_name) + "','" +
  safe(r.course_id) + "','" + safe(r.date) + "','" + safe(r.status) + "')"
);
const sql_query = 'INSERT INTO attendance (student_id, student_name, course_id, date, status) VALUES\n' +
  valueRows.join(',\n') + '\nON CONFLICT DO NOTHING';
return [{ json: { ...$json, sql_query, insertCount: records.length } }];

// ── WF1: Generar Reporte HTML de Asistencia ───────────────────────────────
const data = $input.first().json;
const records = data.records || [];
const now = new Date().toLocaleString('es-GT', { timeZone: 'America/Guatemala' });
const dateStr = new Date().toISOString().split('T')[0];
const reportName = 'attendance_report_' + dateStr + '.html';
const reportFilePath = '/data/shared/output/' + reportName;
const sColors = { present:'#16a34a', absent:'#dc2626', late:'#d97706', excused:'#2563eb' };
const sLabels = { present:'Presente', absent:'Ausente', late:'Tardanza', excused:'Excusado' };
const tableRows = records.map((r, i) =>
  '<tr><td>' + (i+1) + '</td><td><code>' + r.student_id + '</code></td><td>' + r.student_name +
  '</td><td>' + r.course_id + '</td><td>' + r.date +
  '</td><td><span style="background:' + (sColors[r.status]||'#6b7280') + ';color:#fff;padding:2px 10px;border-radius:12px;font-size:11px;font-weight:600">' +
  (sLabels[r.status]||r.status) + '</span></td></tr>'
).join('\n');
const cnt = { p: records.filter(r=>r.status==='present').length, a: records.filter(r=>r.status==='absent').length,
              l: records.filter(r=>r.status==='late').length, e: records.filter(r=>r.status==='excused').length };
const rate = records.length > 0 ? Math.round((cnt.p/records.length)*100) : 0;
const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
<title>Reporte Asistencia ${dateStr}</title><style>
*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',Arial,sans-serif;background:#f1f5f9;color:#1e293b;padding:24px}
.hdr{background:linear-gradient(135deg,#1e40af,#3b82f6);color:#fff;padding:24px;border-radius:12px;margin-bottom:20px}
.hdr h1{font-size:20px}.hdr p{opacity:.85;font-size:13px;margin-top:6px}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:14px;margin-bottom:20px}
.card{background:#fff;border-radius:10px;padding:18px;text-align:center;box-shadow:0 1px 4px rgba(0,0,0,.08)}
.card h2{font-size:1.8em;font-weight:700}.card p{font-size:12px;color:#64748b;margin-top:4px}
.tw{background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,.08)}
table{width:100%;border-collapse:collapse}
th{background:#1e40af;color:#fff;padding:11px 10px;text-align:left;font-size:13px}
td{padding:10px;border-bottom:1px solid #e2e8f0;font-size:13px}tr:last-child td{border:none}tr:hover td{background:#f8fafc}
code{background:#e2e8f0;padding:1px 5px;border-radius:4px;font-size:12px}
.footer{text-align:center;margin-top:16px;color:#94a3b8;font-size:12px}</style></head>
<body>
<div class="hdr"><h1>📋 Reporte de Asistencia Académica</h1>
<p>Generado: ${now} &nbsp;|&nbsp; Registros: ${records.length} &nbsp;|&nbsp; Tasa de asistencia: ${rate}%</p></div>
<div class="stats">
<div class="card"><h2 style="color:#16a34a">${cnt.p}</h2><p>✅ Presentes</p></div>
<div class="card"><h2 style="color:#dc2626">${cnt.a}</h2><p>❌ Ausentes</p></div>
<div class="card"><h2 style="color:#d97706">${cnt.l}</h2><p>⏰ Tardanzas</p></div>
<div class="card"><h2 style="color:#2563eb">${cnt.e}</h2><p>📋 Excusados</p></div>
<div class="card"><h2 style="color:#7c3aed">${rate}%</h2><p>📊 Asistencia</p></div>
</div>
<div class="tw"><table>
<thead><tr><th>#</th><th>ID</th><th>Nombre</th><th>Curso</th><th>Fecha</th><th>Estado</th></tr></thead>
<tbody>${tableRows}</tbody></table></div>
<div class="footer">Sistema automatizacion Académica — n8n | ${dateStr}</div>
</body></html>`;
return [{ json: { ...data, reportName, reportFilePath, generatedAt: now, attendanceRate: rate },
  binary: { report: { data: Buffer.from(html).toString('base64'), mimeType:'text/html', fileName: reportName, fileExtension:'html' } } }];

// ── WF1: Preparar SQL para registrar reporte ─────────────────────────────
const safe = s => String(s||'').replace(/'/g,"''");
const fp = safe($json.reportFilePath || '/data/shared/output/report.html');
const sql_query = "INSERT INTO reports (report_type, file_path, status, records_count) VALUES " +
  "('attendance', '" + fp + "', 'generated', " + ($json.total || 0) + ")";
return [{ json: { ...$json, sql_query } }];

// ── WF1: Preparar SQL para log de errores ─────────────────────────────────
const safe = s => String(s||'').replace(/'/g,"''");
const msg = safe(($json.errors||[]).join(' | '));
const data = safe(JSON.stringify({ errors: $json.errors, errorCount: $json.errorCount }));
const sql_query = "INSERT INTO error_logs (workflow_name, node_name, error_message, error_data) VALUES " +
  "('WF1 - Asistencia CSV', 'Parseo/Validacion CSV', '" + msg + "', '" + data + "')";
return [{ json: { ...$json, sql_query } }];
